WITH base AS (SELECT *, INITCAP(TRIM(location)) AS location_title FROM departments WHERE location <> 'Tokyo'), budget_bucket_summary AS (SELECT CASE WHEN budget >= 3102000 THEN 'high' WHEN budget >= 1944000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget FROM base GROUP BY CASE WHEN budget >= 3102000 THEN 'high' WHEN budget >= 1944000 THEN 'mid' ELSE 'low' END) SELECT * FROM budget_bucket_summary;
